<?php require __DIR__.'/_layout.php';x1_require_role('admin');$db=x1_db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{x1_check_csrf();if(!$db)throw new RuntimeException('SQLite required');$act=(string)($_POST['act']??'add');if($act==='add'){$type=(string)$_POST['type'];if(!in_array($type,['telegram','discord','webhook'],true))throw new RuntimeException('Invalid integration');$cfg=[];if($type==='telegram')$cfg=['bot_token'=>(string)$_POST['bot_token'],'chat_id'=>(string)$_POST['chat_id']];if($type==='discord')$cfg=['webhook_url'=>(string)$_POST['url']];if($type==='webhook')$cfg=['url'=>(string)$_POST['url'],'secret'=>(string)$_POST['secret']];x1_db_exec('INSERT INTO integrations(id,type,name,enabled,config_enc,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',[x1_id(),$type,trim((string)$_POST['name']),1,x1_encrypt_secret(json_encode($cfg,JSON_UNESCAPED_SLASHES)),date('c'),date('c')]);x1_audit('integration_add',$type);}elseif($act==='toggle'){x1_db_exec('UPDATE integrations SET enabled=CASE enabled WHEN 1 THEN 0 ELSE 1 END,updated_at=? WHERE id=?',[date('c'),(string)$_POST['id']]);x1_audit('integration_toggle',(string)$_POST['id']);}elseif($act==='test'){$r=x1_integration_send('test','X1 WAVEO test','Integration test from X1 WAVEO Production Control Plane.');$msg=json_encode($r,JSON_UNESCAPED_SLASHES);}header('Location:integrations.php'.($msg!==''?'?tested=1':''));exit;}catch(Throwable $e){$msg=$e->getMessage();}}$rows=$db?x1_db_all('SELECT id,type,name,enabled,created_at,updated_at FROM integrations ORDER BY created_at DESC'):[];top(tr('Integrations','Integrações'));?><section class="card hero"><div class=eyebrow>OUTBOUND AUTOMATION</div><h2>Telegram · Discord · HTTPS Webhook + HMAC-SHA256</h2></section><?php if(isset($_GET['tested'])):?><section class=notice><?=tr('Integration test was executed. Check the configured destinations and API logs.','O teste de integração foi executado. Verifique os destinos configurados e logs API.')?></section><?php endif?><?php if($msg):?><section class="notice warn"><?=h($msg)?></section><?php endif?><section class=section><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=add><div class=formgrid><label>Name<input name=name required></label><label>Type<select name=type><option>telegram</option><option>discord</option><option>webhook</option></select></label><label>Telegram Bot Token<input type=password name=bot_token></label><label>Telegram Chat ID<input name=chat_id></label><label>Discord / Webhook URL<input name=url></label><label>Webhook HMAC Secret<input type=password name=secret></label></div><button><?=tr('Add integration','Adicionar integração')?></button></form></section><section class=section><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=test><button class=secondary><?=tr('Send test notification','Enviar notificação de teste')?></button></form><table><tr><th>Name</th><th>Type</th><th>Status</th><th></th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['type'])?></td><td><?=$x['enabled']?'Enabled':'Disabled'?></td><td><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=toggle><input type=hidden name=id value="<?=h($x['id'])?>"><button><?=tr('Toggle','Alternar')?></button></form></td></tr><?php endforeach?></table></section><?php bottom();